-- 0005: "Before you switch it on" safety box + outside-content (prompt-injection) flag on every use case.
-- safety = {whatCanGoWrong, whenToStop, humanHandoff}: one short, card-specific sentence each.
-- reads_untrusted_content = the agent reads text written by outsiders (email, inbox, DMs/texts, tickets, reviews, forms, web pages).
-- Mirrors the engine gate in scripts/engine/safety.mjs (30-120 chars per field, fields must differ).
begin;
alter table public.use_cases add column if not exists safety jsonb;
alter table public.use_cases add column if not exists reads_untrusted_content boolean;

update public.use_cases u set safety = jsonb_build_object('whatCanGoWrong', v.w, 'whenToStop', v.s, 'humanHandoff', v.h), reads_untrusted_content = v.f
from (values
  ('write-weekly-client-status-reports-automatically', 'It credits work that isn''t finished, or mentions one client''s project in another client''s update.', 'Pause it the first time a report lists unfinished tasks as done or lands in the wrong client''s inbox.', 'You read and send each update yourself; anything about delays, scope or budget is yours to write.', false),
  ('prep-daily-specials-and-prep-lists-from-inventory', 'It builds the prep list from stale counts, or suggests a special around stock that''s already gone off.', 'Stop trusting it when its lists drift from what the line actually used, or counts stop getting entered.', 'The chef signs off on the list every morning and decides what''s safe to serve; it only suggests.', false),
  ('write-patient-reminder-and-recall-messages', 'A recall goes to a patient who''s already booked, has left the practice, or asked not to be contacted.', 'Pause it if a patient flags a wrong or repeated message, or their details land in a general chat tool.', 'The front desk checks the recall list before anything sends and handles every reply about symptoms or billing.', false),
  ('pre-qualify-rental-and-buyer-inquiries', 'It books a showing in a slot you can''t make, or tells a lead something untrue about the property.', 'Pause it if showings get double-booked, or it starts fielding questions on price or terms.', 'Negotiation, applications and anything not covered by the listing go straight to you.', true),
  ('bring-back-lapsed-customers-with-a-win-back-sequence', 'It sends a cheerful "we miss you" to someone who left after a complaint, or who already unsubscribed.', 'Stop the sequence if unsubscribes or spam complaints jump, or a reply shows it reached the wrong person.', 'Every customer reply comes to you; the agent drafts the sequence, it doesn''t hold the conversation.', false),
  ('write-product-descriptions-for-your-whole-catalog', 'It invents a spec, material or claim (waterproof, organic, one size fits all) that isn''t on the spec sheet.', 'Pause publishing if a return or complaint traces back to something a description promised.', 'Someone checks each description against the spec sheet before it goes live, sizing and safety claims first.', false),
  ('send-a-monthly-newsletter-customers-actually-open', 'It pads the email with a tip or offer you never gave it, or gets a date or price wrong.', 'Hold the send whenever a draft includes anything that wasn''t in your notes.', 'You read the final draft and press send yourself, every month.', false),
  ('write-a-month-of-social-posts-from-one-batch-of-photos', 'A caption names a client or shows an address you didn''t mean to share, or oversells what the job involved.', 'Pause scheduling if a client asks why their home or face is in a post they never approved.', 'You approve the month''s posts before they''re scheduled and answer comments yourself.', false),
  ('keep-a-running-sop-library-from-how-you-already-work', 'It writes a tidy SOP that skips a step you did on screen but never said out loud.', 'Stop using a document the moment someone follows it and gets a different result than you do.', 'The person who actually does the task reviews each SOP before it''s filed as the official version.', false),
  ('turn-meeting-recordings-into-action-items', 'It gives an action to the wrong person, or records a decision nobody actually made.', 'Pause it if people act on a summary that got a decision wrong, or a guest wasn''t told they were being recorded.', 'The meeting owner skims the summary before it''s posted and fixes owners and deadlines.', false),
  ('triage-the-owner-s-inbox-every-morning', 'It files a real complaint under FYI, or drafts a reply agreeing to something you wouldn''t.', 'Pause it if an urgent email turns up in FYI or Junk, or it drafts a polite reply to phishing.', 'You send every reply yourself; anything about money, contracts or staff stays with you.', true),
  ('summarize-contracts-before-you-sign-them', 'The summary misses an auto-renewal, a personal guarantee or a liability clause tucked into the fine print.', 'Stop relying on it if a summary ever contradicts the contract when you check a clause yourself.', 'A lawyer reviews anything high-value, long-term or carrying personal liability before you sign.', false),
  ('track-license-insurance-and-certification-renewals', 'One wrong date in the sheet and the reminder arrives too late, or not at all.', 'If anything lapses without a reminder, stop and re-check every date in the sheet.', 'Each renewal has a named owner; the reminder tells them, it doesn''t renew anything.', false),
  ('draft-estimates-from-site-visit-notes-and-photos', 'It mishears a dictated measurement, or prices a line from an outdated price book.', 'Pause it if an estimate goes out that you later have to honor at a loss.', 'The tech or owner checks quantities and the total before any estimate reaches the customer.', false),
  ('read-receipts-and-supplier-bills-into-your-books', 'It misreads an amount or due date, or books a fake invoice dressed up as a real supplier''s.', 'Pause it if a draft bill doesn''t match the PDF, or a supplier''s bank details suddenly change.', 'Someone approves every draft bill before it''s paid and confirms any new bank details by phone.', true),
  ('get-a-plain-english-weekly-cash-summary', 'It reports a balance from a feed that hasn''t synced, or misses a large bill due that week.', 'Stop leaning on it if a summary doesn''t match your bank balance when you spot-check.', 'Decisions about payroll, borrowing or delaying a bill come from you or your bookkeeper, not the summary.', false),
  ('categorize-bank-transactions-and-flag-the-weird-ones', 'It files a personal or equipment purchase in the wrong category, or misses a duplicate charge.', 'Turn off auto-accept if your bookkeeper keeps undoing its categories.', 'Flagged and unusual charges go to you or your bookkeeper; it never disputes or deletes anything itself.', false),
  ('onboard-new-hires-with-a-day-one-checklist-assistant', 'It answers with an outdated policy, or guesses where the handbook says nothing.', 'Pause it if a new hire acts on an answer about pay, leave or safety that turns out to be wrong.', 'Questions about pay, benefits, safety or complaints go to a manager, not the assistant.', false),
  ('write-job-posts-that-actually-attract-tradespeople', 'It inflates the role, or adds a requirement or perk you don''t actually offer.', 'Rewrite it by hand if applicants keep arriving with the wrong idea about pay or hours.', 'You confirm pay, schedule and any legal wording before the post goes up.', false),
  ('screen-job-applicants-against-a-simple-scorecard', 'It marks down a strong candidate over formatting, or repeats a bias baked into your past hires.', 'Pause it if its scores keep disagreeing with yours, or it cites things not in the application.', 'You read every low-scored application before rejecting it; every hiring decision is yours.', true),
  ('fill-last-minute-cancellations-from-a-waitlist', 'It books two people into one slot, or reads "yes, but could it be later?" as a yes.', 'Pause it the first time someone turns up for a slot that''s already taken.', 'Unclear replies, and anyone asking about price or a different service, go to the front desk.', true),
  ('let-clients-book-reschedule-and-get-reminders-on-their-own', 'It moves an appointment into time you blocked off, or confirms a change the client didn''t ask for.', 'Turn off the AI replies if a client misses an appointment because of a change it made.', 'Refunds, complaints, late-cancel fees and anything urgent go to a person.', true),
  ('plan-tomorrow-s-technician-routes-in-minutes', 'It sends a tech to a job they aren''t qualified for, or ignores a customer''s time window.', 'Stop using its plan once the dispatcher is rewriting most of it every evening.', 'The dispatcher approves the schedule each night and handles every same-day change.', false),
  ('build-a-24-7-faq-assistant-from-your-own-policies', 'It quotes a price or policy wrong, or makes up an answer when your FAQ doesn''t cover the question.', 'Pause it if a customer holds you to something it said that isn''t your policy.', 'Refunds, complaints and anything outside the FAQ go to a person, with the chat attached.', true),
  ('follow-up-after-every-job-and-catch-unhappy-customers-early', 'It sends a review link to someone who complained, or takes a sarcastic "great job" at face value.', 'Pause it if an unhappy customer says they got a review request right after complaining.', 'Every unhappy or unclear reply goes to the owner, who calls back the same day.', true),
  ('draft-replies-to-every-google-review', 'A reply confirms private details about a customer, or sounds defensive about a fair complaint.', 'Pause it if a draft ever mentions an order, visit or name the reviewer didn''t share publicly.', 'You approve every reply and write the ones to angry or detailed negative reviews yourself.', true),
  ('score-and-route-inbound-leads-in-hubspot', 'It scores a good lead low because a form field was blank, or routes it to someone who''s away.', 'Pause routing if reps keep reassigning its picks, or a lead sits untouched for days.', 'Sales reviews the low-scored leads every week; nobody is dropped on its score alone.', true),
  ('turn-missed-calls-into-text-conversations', 'It promises a callback time or price you can''t meet, or keeps texting someone who replied stop.', 'Pause it if a caller complains about the texts, or an urgent job sits unanswered in the thread.', 'Once the job details are in, a person calls back; emergencies get flagged to you straight away.', true),
  ('answer-every-web-lead-within-five-minutes-even-after-hours', 'It offers a booking time that''s already taken, or answers a pricing question it shouldn''t.', 'Pause it if leads get double-booked, or keep asking to speak to someone real.', 'When a lead asks for a quote, a person or anything off-script, a human takes over the thread.', true),
  ('reconcile-stripe-payouts-to-invoices-automatically', 'It matches a payout to the wrong invoice when amounts look alike, which can hide a missing payment.', 'Stop auto-matching if your books and Stripe disagree at month-end.', 'Anything unmatched goes to your bookkeeper; don''t let it mark an invoice paid on a guess.', false),
  ('send-a-payment-link-the-minute-a-job-is-marked-done', 'The invoice goes out with the wrong amount, or before the job is actually finished.', 'Pause it if a customer gets a link for a job still in progress, or gets two links for one job.', 'Disputed amounts, discounts and refunds are handled by you or the office, not the automation.', false),
  ('chase-overdue-invoices-without-awkward-phone-calls', 'It nudges a customer who already paid, or sends a firm notice to one on an agreed payment plan.', 'Pause it if a customer says they''ve paid or are on a plan and still got a reminder.', 'Any customer who replies, and anything past your firm stage, comes to you.', false),
  ('fill-empty-calendar-slots-and-draft-social-posts-from-notion-ucr0', 'It fills open slots with the wrong priorities, or drafts a prospect comment that misjudges the tone.', 'Pause it when conflicting rules trip it up, or it queues client work to post without your sign-off.', 'You approve every caption and every prospect comment before anything goes public.', true),
  ('let-an-ai-voice-agent-answer-the-phone-so-you-can-get-on-with-the-work-pz45', 'It mishears a name, postcode or email, or keeps a caller who wants a person talking to a bot.', 'Pause it if your conversion rate falls and stays down, or callers keep asking for a human.', 'Anyone who asks for a person, or calls about something off its list, gets a callback from the team.', true)
) as v(slug, w, s, h, f)
where u.slug = v.slug;

-- Any row not covered above must be fixed by hand before this migration can apply.
do $$ begin if exists (select 1 from public.use_cases where safety is null or reads_untrusted_content is null) then
  raise exception 'use_cases rows missing safety backfill: %', (select string_agg(slug, ', ') from public.use_cases where safety is null or reads_untrusted_content is null); end if; end $$;

alter table public.use_cases alter column reads_untrusted_content set not null;
alter table public.use_cases alter column reads_untrusted_content set default false;
alter table public.use_cases alter column safety set not null;
alter table public.use_cases drop constraint if exists use_cases_safety_check;
alter table public.use_cases add constraint use_cases_safety_check check (
  jsonb_typeof(safety) = 'object'
  and jsonb_typeof(safety->'whatCanGoWrong') = 'string' and char_length(btrim(safety->>'whatCanGoWrong')) between 30 and 120
  and jsonb_typeof(safety->'whenToStop') = 'string' and char_length(btrim(safety->>'whenToStop')) between 30 and 120
  and jsonb_typeof(safety->'humanHandoff') = 'string' and char_length(btrim(safety->>'humanHandoff')) between 30 and 120
  and lower(btrim(safety->>'whatCanGoWrong')) <> lower(btrim(safety->>'whenToStop'))
  and lower(btrim(safety->>'whatCanGoWrong')) <> lower(btrim(safety->>'humanHandoff'))
  and lower(btrim(safety->>'whenToStop')) <> lower(btrim(safety->>'humanHandoff'))
);
commit;
